import * as THREE from 'three/webgpu';
import { MeshBasicNodeMaterial } from 'three/tsl';

export default function createNode(config, ctx) {
  const group = new THREE.Group();

  // Track resources for cleanup
  const cleanup_resources = {
    geometries: [],
    materials: [],
    textures: [],
  };

  // ===== SCENE PLACEMENT =====
  const scenePos = config.scenePosition || {};
  const position = scenePos.position || [0, -2.85, 0.26];
  const rotation = scenePos.rotation || [0, 0, 0];
  const scale = scenePos.scale || [1, 1, 1];

  group.position.set(position[0], position[1], position[2]);
  group.rotation.set(rotation[0], rotation[1], rotation[2]);
  group.scale.set(scale[0], scale[1], scale[2]);

  // ===== COLOR PALETTE =====
  const colors = {
    ink: new THREE.Color(config.colors?.ink || '#16161d'),
    paper: new THREE.Color(config.colors?.paper || '#e8ecf2'),
    accent: new THREE.Color(config.colors?.accent || '#ff2a38'),
    surface: new THREE.Color(config.colors?.surface || '#0b0b10'),
  };

  // ===== BUTTON BACKGROUND PLANE =====
  const buttonGeom = new THREE.PlaneGeometry(2.4, 0.6);
  cleanup_resources.geometries.push(buttonGeom);

  // Load brushed metal texture
  const metalTexture = ctx.textureLoader.load(
    config.assets?.imageUrl || '/prism-assets/chrome/brushed-metal.map.png'
  );
  cleanup_resources.textures.push(metalTexture);

  const buttonMat = new MeshBasicNodeMaterial({
    map: metalTexture,
    color: colors.paper,
    transparent: true,
  });
  cleanup_resources.materials.push(buttonMat);

  const buttonMesh = new THREE.Mesh(buttonGeom, buttonMat);
  group.add(buttonMesh);

  // ===== TEXT CONTENT VIA FONT ATLAS =====
  if (config.textContent && config.textContent.length > 0) {
    const textContent = config.textContent[0];

    // Create MSDF text mesh using fontAtlas
    const textMesh = ctx.fontAtlas.create({
      text: textContent,
      font: 'Lora',
      size: 0.34, // headline type scale
      weight: 400,
      color: colors.ink,
      align: 'center',
      anchorX: 'center',
      anchorY: 'middle',
    });

    if (textMesh) {
      textMesh.position.z = 0.01;
      group.add(textMesh);
    }
  }

  // ===== EVENT HANDLERS =====
  group.userData.handlers = {
    click: (event) => {
      // CTA button interaction
    },
  };

  // ===== RESOURCE CLEANUP =====
  group.userData.cleanup = () => {
    cleanup_resources.geometries.forEach((g) => g.dispose());
    cleanup_resources.materials.forEach((m) => m.dispose());
    cleanup_resources.textures.forEach((t) => t.dispose());
  };

  return group;
}
